-- insert-las-palmas-centers.sql
-- Inserta los 37 centros de educacion infantil de primer ciclo (0-3 anos)
-- del termino municipal de Las Palmas de Gran Canaria capital investigados y
-- humanizados en este sprint.
-- Fuentes primarias: "Directorio de centros educativos de Canarias" (Consejeria de
-- Educacion, Formacion Profesional, Actividad Fisica y Deportes, Gobierno de
-- Canarias, portal datos.canarias.es), filtrado por Municipio='LAS PALMAS DE GRAN
-- CANARIA' AND DesEtapaCentro in ['EEI','CPEI']. Complementado con la web oficial
-- del Ayuntamiento de Las Palmas de Gran Canaria (Escuelas Infantiles Municipales,
-- gestionadas por la empresa municipal TRASA, 11 centros) y con webs oficiales
-- propias de un subconjunto de centros privados para confirmar servicios concretos
-- del enum CenterService.
-- Ver docs/data-sources-las-palmas.md y data/enrichment/las-palmas-centers.json.
--
-- Ambito: unicamente el termino municipal de Las Palmas de Gran Canaria capital
-- (Municipio='LAS PALMAS DE GRAN CANARIA' en la fuente oficial, valor exacto).
-- Se excluyen explicitamente el resto de municipios de la isla de Gran Canaria
-- (Telde, Santa Brigida, Arucas, San Bartolome de Tirajana, etc.), aunque
-- aparecieran en la misma fuente insular/autonomica.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por RLS
-- hasta cambiarlos a 'published' manualmente tras auditoria, igual que en Madrid,
-- Barcelona, Valencia, Zaragoza, Murcia, Sevilla, Palma, Malaga y Alicante).
-- No toca ningun centro de las 9 zonas ya integradas.
-- No borra ni modifica filas existentes (upsert por slug: si un slug ya existe se
-- actualiza, no se duplica).
-- Generado: 2026-07-12. Revisar antes de ejecutar.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "las-palmas-de-gran-canaria" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('las-palmas-de-gran-canaria', 'Las Palmas de Gran Canaria', 'Las Palmas', 'Canarias')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
)
